// Split vendors array into individual items for processing
const body = $input.first().json.body || $input.first().json;
const vendors = body.vendors || [];

if (!vendors.length) {
  return [{ json: { _no_vendors: true } }];
}

return vendors.map(v => ({
  json: {
    vendor_name: v.vendor_name || v.name || '',
    website: (v.website || '').replace(/\/$/, ''),
    // Only pass fields that are currently empty so we can skip already-enriched vendors
    _needs_founded: !v.founded,
    _needs_hq: !v.hq_address,
    _needs_funding_stage: !v.funding_stage,
    _needs_total_funding: !v.total_funding,
  }
}));

// Derive a Tracxn slug from the website domain or vendor name.
// Mirrors derive_tracxn_slug() in services/enrichment/tracxn_enricher.py
const item = $input.first().json;

function deriveSlug(vendorName, website) {
  if (website) {
    const domain = website.replace(/^https?:\/\/(?:www\.)?/, '').split('/')[0];
    const base = domain.split('.')[0];
    if (base && base.length >= 3) return base.toLowerCase();
  }
  return vendorName.toLowerCase().replace(/[^a-z0-9 ]/g, '').trim().replace(/ +/g, '-');
}

const slug = deriveSlug(item.vendor_name, item.website);

return [{
  json: {
    ...item,
    tracxn_slug: slug,
    tracxn_url: `https://tracxn.com/d/companies/${slug}/`,
  }
}];

// Validate the Tracxn response and extract visible text.
// A miss is a 404, non-200, or page with less than 100 words.
const item = $input.first().json;

const statusCode = item.$response?.statusCode || item.statusCode || 0;
const body = String(item.$response?.body || item.body || '');

// Strip HTML to visible text
const visibleText = body
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&[a-z]+;/gi, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const wordCount = visibleText ? visibleText.split(' ').filter(w => w.length > 1).length : 0;
const isReachable = statusCode >= 200 && statusCode < 400 && wordCount >= 100;

return [{
  json: {
    vendor_name: item.vendor_name,
    website: item.website,
    tracxn_slug: item.tracxn_slug,
    tracxn_url: item.tracxn_url,
    _needs_founded: item._needs_founded,
    _needs_hq: item._needs_hq,
    _needs_funding_stage: item._needs_funding_stage,
    _needs_total_funding: item._needs_total_funding,
    page_valid: isReachable,
    visible_text: isReachable ? visibleText.slice(0, 10000) : '',
    raw_html: isReachable ? body.slice(0, 50000) : '',
    status_code: statusCode,
    word_count: wordCount,
  }
}];

// Extract founded, hq_address, funding_stage, total_funding from Tracxn teaser page.
// Mirrors _parse_tracxn_page() in services/enrichment/tracxn_enricher.py
const item = $input.first().json;
const text = item.visible_text || '';
const html = item.raw_html || '';

// Founded year — first 4-digit year in reasonable range
const foundedMatch = text.match(/\b((?:19|20)\d{2})\b/);
const founded = foundedMatch ? foundedMatch[1] : null;

// HQ address — try JSON-LD first, then text heuristics
let hq_address = null;
const ldMatches = [...html.matchAll(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)];
for (const m of ldMatches) {
  try {
    const data = JSON.parse(m[1]);
    const addr = data.address || {};
    if (typeof addr === 'object') {
      const parts = [addr.addressLocality, addr.addressRegion, addr.addressCountry].filter(Boolean);
      if (parts.length) { hq_address = parts.join(', '); break; }
    }
  } catch(e) {}
}
if (!hq_address) {
  const hqMatch = text.match(/(?:Headquarters|HQ)[:\s]+([A-Z][^\n,;|]{3,50})/);
  if (hqMatch) hq_address = hqMatch[1].trim();
}

// Funding stage — ordered most-specific first
const fundingStageRe = /Series\s+[A-Z]{1,2}|Pre-Seed|Seed(?:\s+Round)?|IPO|Acquired|Private Equity|Growth|Bootstrapped|Angel/i;
const stageMatch = text.match(fundingStageRe);
const funding_stage = stageMatch ? stageMatch[0].trim() : null;

// Total funding — e.g. $42.5M, $1.2B, $500K
const fundingAmtMatch = text.match(/\$[\d.,]+\s*[BMKbmk]/);
const total_funding = fundingAmtMatch ? fundingAmtMatch[0].trim() : null;

// Only include fields that were empty and that Tracxn found
const payload = {
  vendor_name: item.vendor_name,
  website: item.website,
};
if (item._needs_founded && founded) payload.founded = founded;
if (item._needs_hq && hq_address) payload.hq_address = hq_address;
if (item._needs_funding_stage && funding_stage) payload.funding_stage = funding_stage;
if (item._needs_total_funding && total_funding) payload.total_funding = total_funding;

const hasData = !!(founded || hq_address || funding_stage || total_funding);
const fieldsFound = Object.keys(payload).filter(k => !['vendor_name','website'].includes(k));

return [{
  json: {
    ...payload,
    tracxn_url: item.tracxn_url,
    _has_data: hasData && fieldsFound.length > 0,
    _fields_found: fieldsFound,
  }
}];

// Page unreachable or too short — record as miss
const item = $input.first().json;
return [{
  json: {
    vendor_name: item.vendor_name,
    website: item.website,
    tracxn_url: item.tracxn_url,
    _miss: true,
    _has_data: false,
    _fields_found: [],
  }
}];
